/**
 * Admin user detail component
 *
 * Displays detailed information about a specific user including:
 * - Account information (email, auth methods, admin status)
 * - Credit balance and stats
 * - Deposit history
 * - Transaction history
 *
 * Requires system admin privileges.
 */

import { useState, useEffect, useCallback, useMemo } from 'react';
import { useAdminUsers } from '../../hooks/useAdminUsers';
import type {
  AdminReferredUsersResponse,
  AdminUser,
  AdminUserCreditsResponse,
  AdminUserChatsResponse,
  AdminChatSession,
  AdminCreditTransactionItem,
  ListUsersParams,
  ReferredUserItem,
} from '../../types';
import type { AdminDepositListResponse, AdminDepositItem } from '../../types/deposit';
import type { AdminUserKycResponse, AdminUserKycSession } from '../../types/adminUser';
import type {
  AdminUserAccreditationResponse,
  AccreditationSubmissionItem,
} from '../../types/accreditation';
import { AdminUserApiClient } from '../../utils/adminUserApi';
import { useCedrosLogin } from '../../context/useCedrosLogin';

export interface AdminUserDetailProps {
  /** User ID to display */
  userId: string;
  /** Callback when back button is clicked */
  onBack: () => void;
  /** Current user's ID (to prevent self-demotion) */
  currentUserId?: string;
  /** Callback when edit is clicked (parent handles modal) */
  onEditUser?: (user: AdminUser) => void;
  /** Callback when credits adjustment is clicked (parent handles modal) */
  onAdjustCredits?: (user: AdminUser) => void;
  /** Whether cedros-pay is enabled (shows Chats tab) */
  cedrosPayEnabled?: boolean;
  /** Additional CSS classes */
  className?: string;
}

type TabId = 'deposits' | 'transactions' | 'chats' | 'referrals' | 'kyc' | 'accreditation';

function formatDate(dateString: string): string {
  const date = new Date(dateString);
  return date.toLocaleDateString(undefined, {
    year: 'numeric',
    month: 'short',
    day: 'numeric',
  });
}

function formatDateTime(dateString: string): string {
  const date = new Date(dateString);
  return date.toLocaleString(undefined, {
    year: 'numeric',
    month: 'short',
    day: 'numeric',
    hour: '2-digit',
    minute: '2-digit',
  });
}

function formatSol(lamports: number | null | undefined): string {
  if (lamports === null || lamports === undefined) return '—';
  const sol = lamports / 1_000_000_000;
  return `${sol.toFixed(4)} SOL`;
}

function formatCredits(lamports: number | null | undefined): string {
  if (lamports === null || lamports === undefined) return '—';
  // Credits are stored in lamports but displayed as a simple number
  const credits = lamports / 1_000_000_000;
  return credits.toFixed(4);
}

function formatTxType(txType: string): string {
  const typeMap: Record<string, string> = {
    DEPOSIT: 'Deposit',
    SPEND: 'Spend',
    ADJUSTMENT: 'Adjustment',
    REFUND: 'Refund',
  };
  return typeMap[txType.toUpperCase()] || txType;
}

function formatTxDescription(txType: string, referenceType?: string): string {
  if (referenceType) {
    const refMap: Record<string, string> = {
      deposit: 'Credit deposit',
      purchase: 'Purchase',
      api_call: 'API usage',
      subscription: 'Subscription',
      refund: 'Refund',
      bonus: 'Bonus credit',
      promo: 'Promotional credit',
      correction: 'Balance correction',
    };
    return refMap[referenceType.toLowerCase()] || referenceType;
  }
  // Fallback based on tx type
  const typeDescriptions: Record<string, string> = {
    DEPOSIT: 'Credit added',
    SPEND: 'Credit used',
    ADJUSTMENT: 'Manual adjustment',
    REFUND: 'Credit refunded',
  };
  return typeDescriptions[txType.toUpperCase()] || '—';
}

/**
 * Admin user detail display
 *
 * Shows comprehensive user information with deposit and credit history.
 */
export function AdminUserDetail({
  userId,
  onBack,
  currentUserId,
  onEditUser,
  onAdjustCredits,
  cedrosPayEnabled = false,
  className = '',
}: AdminUserDetailProps) {
  const { config, _internal } = useCedrosLogin();
  const {
    isLoading,
    getUser,
    getUserDeposits,
    getUserCredits,
    getUserChats,
    getUserReferrals,
    deleteUser,
    forcePasswordReset,
    clearError,
  } = useAdminUsers();

  const kycApiClient = useMemo(
    () =>
      new AdminUserApiClient(
        config.serverUrl,
        config.requestTimeout,
        config.retryAttempts,
        _internal?.getAccessToken
      ),
    [config.serverUrl, config.requestTimeout, config.retryAttempts, _internal]
  );

  const [user, setUser] = useState<AdminUser | null>(null);
  const [credits, setCredits] = useState<AdminUserCreditsResponse | null>(null);
  const [deposits, setDeposits] = useState<AdminDepositListResponse | null>(null);
  const [chats, setChats] = useState<AdminUserChatsResponse | null>(null);
  const [referrals, setReferrals] = useState<AdminReferredUsersResponse | null>(null);
  const [kycData, setKycData] = useState<AdminUserKycResponse | null>(null);
  const [accreditationData, setAccreditationData] =
    useState<AdminUserAccreditationResponse | null>(null);
  const [activeTab, setActiveTab] = useState<TabId>('deposits');
  const [userError, setUserError] = useState<string | null>(null);
  const [creditsError, setCreditsError] = useState<string | null>(null);
  const [depositsError, setDepositsError] = useState<string | null>(null);
  const [chatsError, setChatsError] = useState<string | null>(null);
  const [referralsError, setReferralsError] = useState<string | null>(null);
  const [kycError, setKycError] = useState<string | null>(null);
  const [accreditationError, setAccreditationError] = useState<string | null>(null);
  const [actionInProgress, setActionInProgress] = useState(false);

  // Pagination state
  const [depositsOffset, setDepositsOffset] = useState(0);
  const [transactionsOffset, setTransactionsOffset] = useState(0);
  const [chatsOffset, setChatsOffset] = useState(0);
  const [referralsOffset, setReferralsOffset] = useState(0);
  const pageSize = 10;

  const fetchUser = useCallback(async () => {
    try {
      const userData = await getUser(userId);
      setUser(userData);
      setUserError(null);
    } catch (err) {
      setUserError(err instanceof Error ? err.message : 'Failed to load user');
    }
  }, [userId, getUser]);

  const fetchDeposits = useCallback(async () => {
    try {
      const params: ListUsersParams = { limit: pageSize, offset: depositsOffset };
      const depositsData = await getUserDeposits(userId, params);
      setDeposits(depositsData);
      setDepositsError(null);
    } catch (err) {
      setDepositsError(err instanceof Error ? err.message : 'Failed to load deposits');
    }
  }, [userId, getUserDeposits, depositsOffset]);

  const fetchCredits = useCallback(async () => {
    try {
      const params: ListUsersParams = { limit: pageSize, offset: transactionsOffset };
      const creditsData = await getUserCredits(userId, params);
      setCredits(creditsData);
      setCreditsError(null);
    } catch (err) {
      setCreditsError(err instanceof Error ? err.message : 'Failed to load credits');
    }
  }, [userId, getUserCredits, transactionsOffset]);

  const fetchChats = useCallback(async () => {
    if (!cedrosPayEnabled) return;
    try {
      const params: ListUsersParams = { limit: pageSize, offset: chatsOffset };
      const chatsData = await getUserChats(userId, params);
      setChats(chatsData);
      setChatsError(null);
    } catch (err) {
      setChatsError(err instanceof Error ? err.message : 'Failed to load chat history');
    }
  }, [userId, getUserChats, chatsOffset, cedrosPayEnabled]);

  const fetchReferrals = useCallback(async () => {
    try {
      const params: ListUsersParams = { limit: pageSize, offset: referralsOffset };
      const data = await getUserReferrals(userId, params);
      setReferrals(data);
      setReferralsError(null);
    } catch (err) {
      setReferralsError(err instanceof Error ? err.message : 'Failed to load referrals');
    }
  }, [userId, getUserReferrals, referralsOffset]);

  const fetchKyc = useCallback(async () => {
    try {
      const data = await kycApiClient.getUserKyc(userId);
      setKycData(data);
      setKycError(null);
    } catch (err) {
      setKycError(err instanceof Error ? err.message : 'Failed to load KYC data');
    }
  }, [userId, kycApiClient]);

  const fetchAccreditation = useCallback(async () => {
    try {
      const data = await kycApiClient.getUserAccreditation(userId);
      setAccreditationData(data);
      setAccreditationError(null);
    } catch (err) {
      setAccreditationError(
        err instanceof Error ? err.message : 'Failed to load accreditation data'
      );
    }
  }, [userId, kycApiClient]);

  const handleAccreditationOverride = useCallback(
    async (status: string) => {
      try {
        await kycApiClient.overrideAccreditationStatus(userId, status);
        await fetchAccreditation();
      } catch (err) {
        setAccreditationError(
          err instanceof Error ? err.message : 'Failed to override accreditation status'
        );
      }
    },
    [userId, kycApiClient, fetchAccreditation]
  );

  const handleAccreditationReview = useCallback(
    async (
      submissionId: string,
      approved: boolean,
      reviewerNotes?: string,
      rejectionReason?: string
    ) => {
      try {
        await kycApiClient.reviewAccreditation(
          submissionId,
          approved,
          reviewerNotes,
          rejectionReason
        );
        await fetchAccreditation();
      } catch (err) {
        setAccreditationError(
          err instanceof Error ? err.message : 'Failed to review accreditation submission'
        );
      }
    },
    [kycApiClient, fetchAccreditation]
  );

  const handleKycOverride = useCallback(
    async (status: string) => {
      try {
        await kycApiClient.overrideUserKyc(userId, status);
        await fetchKyc();
      } catch (err) {
        setKycError(err instanceof Error ? err.message : 'Failed to override KYC status');
      }
    },
    [userId, kycApiClient, fetchKyc]
  );

  // Initial load
  useEffect(() => {
    fetchUser();
    fetchDeposits();
    fetchCredits();
    fetchReferrals();
    fetchKyc();
    fetchAccreditation();
    if (cedrosPayEnabled) {
      fetchChats();
    }
  }, [fetchUser, fetchDeposits, fetchCredits, fetchChats, fetchReferrals, fetchKyc, fetchAccreditation, cedrosPayEnabled]);

  const handleDelete = async () => {
    if (!user) return;
    if (user.id === currentUserId) {
      alert('You cannot delete your own account');
      return;
    }
    if (user.isSystemAdmin) {
      alert('Cannot delete a system admin. Remove admin status first.');
      return;
    }

    const confirmed = window.confirm(
      `Are you sure you want to delete ${user.name || user.email || 'this user'}? This action cannot be undone.`
    );
    if (!confirmed) return;

    setActionInProgress(true);
    try {
      await deleteUser(user.id);
      onBack();
    } catch {
      // Error handled by hook
    } finally {
      setActionInProgress(false);
    }
  };

  const handlePasswordReset = async () => {
    if (!user?.email) {
      alert('User has no email address');
      return;
    }

    const confirmed = window.confirm(`Send a password reset email to ${user.email}?`);
    if (!confirmed) return;

    setActionInProgress(true);
    try {
      await forcePasswordReset(user.id);
      alert('Password reset email sent');
    } catch {
      // Error handled by hook
    } finally {
      setActionInProgress(false);
    }
  };

  // Pagination handlers
  const depositsTotalPages = deposits ? Math.ceil(deposits.total / pageSize) : 0;
  const depositsCurrentPage = Math.floor(depositsOffset / pageSize) + 1;

  const transactionsTotalPages = credits ? Math.ceil(credits.totalTransactions / pageSize) : 0;
  const transactionsCurrentPage = Math.floor(transactionsOffset / pageSize) + 1;

  const goToDepositsPage = (page: number) => {
    setDepositsOffset((page - 1) * pageSize);
  };

  const goToTransactionsPage = (page: number) => {
    setTransactionsOffset((page - 1) * pageSize);
  };

  const chatsTotalPages = chats ? Math.ceil(chats.total / pageSize) : 0;
  const chatsCurrentPage = Math.floor(chatsOffset / pageSize) + 1;

  const goToChatsPage = (page: number) => {
    setChatsOffset((page - 1) * pageSize);
  };

  const referralsTotalPages = referrals ? Math.ceil(referrals.total / pageSize) : 0;
  const referralsCurrentPage = Math.floor(referralsOffset / pageSize) + 1;

  const goToReferralsPage = (page: number) => {
    setReferralsOffset((page - 1) * pageSize);
  };

  // Critical error - user fetch failed
  if (userError) {
    return (
      <div className={`cedros-admin-user-detail cedros-admin-user-detail-error ${className}`}>
        <button
          type="button"
          className="cedros-button cedros-button-outline cedros-button-sm"
          onClick={onBack}
        >
          Back
        </button>
        <p className="cedros-admin-error">{userError}</p>
        <button
          type="button"
          className="cedros-button cedros-button-outline"
          onClick={() => {
            clearError();
            setUserError(null);
            fetchUser();
          }}
        >
          Retry
        </button>
      </div>
    );
  }

  // Loading state
  if (isLoading && !user) {
    return (
      <div className={`cedros-admin-user-detail cedros-admin-user-detail-loading ${className}`}>
        <span className="cedros-admin-loading-indicator" />
        <span className="cedros-admin-loading-text">Loading user...</span>
      </div>
    );
  }

  if (!user) {
    return (
      <div className={`cedros-admin-user-detail ${className}`}>
        <button
          type="button"
          className="cedros-button cedros-button-outline cedros-button-sm"
          onClick={onBack}
        >
          Back
        </button>
        <p className="cedros-admin-empty-message">User not found.</p>
      </div>
    );
  }

  const isCurrentUser = user.id === currentUserId;

  return (
    <div className={`cedros-admin-user-detail ${className}`}>
      {/* Header */}
      <div className="cedros-admin-user-detail-header">
        <button
          type="button"
          className="cedros-button cedros-button-outline cedros-button-sm cedros-admin-back-btn"
          onClick={onBack}
        >
          Back to Users
        </button>
        <div className="cedros-admin-user-detail-actions">
          {onEditUser && (
            <button
              type="button"
              className="cedros-button cedros-button-outline cedros-button-sm"
              onClick={() => onEditUser(user)}
              disabled={actionInProgress}
            >
              Edit
            </button>
          )}
          {user.email && (
            <button
              type="button"
              className="cedros-button cedros-button-outline cedros-button-sm"
              onClick={handlePasswordReset}
              disabled={actionInProgress}
            >
              Reset Password
            </button>
          )}
          {onAdjustCredits && (
            <button
              type="button"
              className="cedros-button cedros-button-outline cedros-button-sm"
              onClick={() => onAdjustCredits(user)}
              disabled={actionInProgress}
            >
              Adjust Credits
            </button>
          )}
          {!isCurrentUser && !user.isSystemAdmin && (
            <button
              type="button"
              className="cedros-button cedros-button-outline cedros-button-sm cedros-admin-btn-danger"
              onClick={handleDelete}
              disabled={actionInProgress}
            >
              Delete
            </button>
          )}
        </div>
      </div>

      {/* User Info Section */}
      <div className="cedros-admin-user-detail-info">
        <div className="cedros-admin-user-detail-avatar">
          {user.picture ? (
            <img
              src={user.picture}
              alt={user.name || user.email || 'User'}
              className="cedros-admin-user-detail-avatar-img"
              referrerPolicy="no-referrer"
            />
          ) : (
            <span className="cedros-admin-user-detail-avatar-placeholder">
              {(user.name?.[0] || user.email?.[0] || '?').toUpperCase()}
            </span>
          )}
        </div>
        <div className="cedros-admin-user-detail-meta">
          <h2 className="cedros-admin-user-detail-name">
            {user.name || 'Unknown'}
            {isCurrentUser && <span className="cedros-admin-user-you">(you)</span>}
          </h2>
          <p className="cedros-admin-user-detail-email">
            {user.email || 'No email'}
            {user.emailVerified && (
              <span className="cedros-admin-verified-badge" title="Email verified">
                Verified
              </span>
            )}
          </p>
          {user.isSystemAdmin && (
            <div className="cedros-admin-user-detail-badges">
              <span className="cedros-admin-admin-badge cedros-admin-admin-badge-yes">
                System Admin
              </span>
            </div>
          )}
          <div className="cedros-admin-user-detail-methods">
            <span className="cedros-admin-user-detail-methods-label">Auth Methods:</span>
            {user.authMethods.length > 0 ? (
              user.authMethods.map((method) => (
                <span
                  key={method}
                  className={`cedros-admin-auth-badge cedros-admin-auth-badge-${method}`}
                >
                  {method}
                </span>
              ))
            ) : (
              <span className="cedros-admin-auth-badge cedros-admin-auth-badge-none">none</span>
            )}
          </div>
          <p className="cedros-admin-user-detail-dates">
            Registered: {formatDate(user.createdAt)} | Updated: {formatDate(user.updatedAt)}
          </p>
          {user.referralCode && (
            <div className="cedros-admin-user-detail-referral">
              <span className="cedros-admin-user-detail-referral-label">Referral:</span>
              <span className="cedros-admin-user-detail-referral-code">{user.referralCode}</span>
              {user.referralCount !== undefined && user.referralCount > 0 && (
                <span className="cedros-admin-user-detail-referral-count">
                  ({user.referralCount} referred)
                </span>
              )}
              {user.referredBy && (
                <span className="cedros-admin-user-detail-referred-by">
                  Referred by:{' '}
                  <button
                    type="button"
                    className="cedros-admin-user-uuid-link"
                    onClick={() => navigator.clipboard?.writeText(user.referredBy!)}
                    title="Click to copy referrer UUID"
                  >
                    {user.referredBy}
                  </button>
                </span>
              )}
            </div>
          )}
        </div>
      </div>

      {/* Stats Cards */}
      {creditsError ? (
        <div className="cedros-admin-stats-error">
          <p className="cedros-admin-error-inline">{creditsError}</p>
          <button
            type="button"
            className="cedros-button cedros-button-outline cedros-button-sm"
            onClick={() => {
              setCreditsError(null);
              fetchCredits();
            }}
          >
            Retry
          </button>
        </div>
      ) : credits ? (
        <div className="cedros-admin-user-detail-stats">
          <div className="cedros-admin-stat-card">
            <span className="cedros-admin-stat-label">Credit Balance</span>
            <span className="cedros-admin-stat-value">
              {formatCredits(credits.stats.currentBalanceLamports)}
            </span>
          </div>
          <div className="cedros-admin-stat-card">
            <span className="cedros-admin-stat-label">Total Credited</span>
            <span className="cedros-admin-stat-value">
              {formatCredits(credits.stats.totalDepositedLamports)}
            </span>
          </div>
          <div className="cedros-admin-stat-card">
            <span className="cedros-admin-stat-label">Total Spent</span>
            <span className="cedros-admin-stat-value">
              {formatCredits(credits.stats.totalSpentLamports)}
            </span>
          </div>
          <div className="cedros-admin-stat-card">
            <span className="cedros-admin-stat-label">Deposits</span>
            <span className="cedros-admin-stat-value">{credits.stats.depositCount}</span>
          </div>
          <div className="cedros-admin-stat-card">
            <span className="cedros-admin-stat-label">Transactions</span>
            <span className="cedros-admin-stat-value">{credits.stats.spendCount}</span>
          </div>
        </div>
      ) : (
        <div className="cedros-admin-stats-loading">
          <span className="cedros-admin-loading-indicator" />
          <span>Loading credit stats...</span>
        </div>
      )}

      {/* Tabs */}
      <div className="cedros-admin-user-detail-tabs">
        <button
          type="button"
          className={`cedros-admin-tab ${activeTab === 'deposits' ? 'cedros-admin-tab-active' : ''}`}
          onClick={() => setActiveTab('deposits')}
        >
          Deposits ({deposits?.total ?? 0})
        </button>
        <button
          type="button"
          className={`cedros-admin-tab ${activeTab === 'transactions' ? 'cedros-admin-tab-active' : ''}`}
          onClick={() => setActiveTab('transactions')}
        >
          Credits ({credits?.totalTransactions ?? 0})
        </button>
        {cedrosPayEnabled && (
          <button
            type="button"
            className={`cedros-admin-tab ${activeTab === 'chats' ? 'cedros-admin-tab-active' : ''}`}
            onClick={() => setActiveTab('chats')}
          >
            Chats ({chats?.total ?? 0})
          </button>
        )}
        <button
          type="button"
          className={`cedros-admin-tab ${activeTab === 'referrals' ? 'cedros-admin-tab-active' : ''}`}
          onClick={() => setActiveTab('referrals')}
        >
          Referrals ({referrals?.total ?? user.referralCount ?? 0})
        </button>
        <button
          type="button"
          className={`cedros-admin-tab ${activeTab === 'kyc' ? 'cedros-admin-tab-active' : ''}`}
          onClick={() => setActiveTab('kyc')}
        >
          KYC ({kycData?.totalSessions ?? 0})
        </button>
        <button
          type="button"
          className={`cedros-admin-tab ${activeTab === 'accreditation' ? 'cedros-admin-tab-active' : ''}`}
          onClick={() => setActiveTab('accreditation')}
        >
          Accreditation ({accreditationData?.totalSubmissions ?? 0})
        </button>
      </div>

      {/* Tab Content */}
      <div className="cedros-admin-user-detail-content">
        {activeTab === 'deposits' && (
          <DepositsTab
            deposits={deposits?.deposits ?? []}
            total={deposits?.total ?? 0}
            currentPage={depositsCurrentPage}
            totalPages={depositsTotalPages}
            onPageChange={goToDepositsPage}
            isLoading={isLoading}
            error={depositsError}
            onRetry={() => {
              setDepositsError(null);
              fetchDeposits();
            }}
          />
        )}
        {activeTab === 'transactions' && (
          <TransactionsTab
            transactions={credits?.transactions ?? []}
            total={credits?.totalTransactions ?? 0}
            currentPage={transactionsCurrentPage}
            totalPages={transactionsTotalPages}
            onPageChange={goToTransactionsPage}
            error={creditsError}
            onRetry={() => {
              setCreditsError(null);
              fetchCredits();
            }}
            isLoading={isLoading}
          />
        )}
        {activeTab === 'chats' && cedrosPayEnabled && (
          <ChatsTab
            sessions={chats?.sessions ?? []}
            total={chats?.total ?? 0}
            currentPage={chatsCurrentPage}
            totalPages={chatsTotalPages}
            onPageChange={goToChatsPage}
            error={chatsError}
            onRetry={() => {
              setChatsError(null);
              fetchChats();
            }}
            isLoading={isLoading}
          />
        )}
        {activeTab === 'referrals' && (
          <ReferralsTab
            referrals={referrals?.users ?? []}
            total={referrals?.total ?? 0}
            currentPage={referralsCurrentPage}
            totalPages={referralsTotalPages}
            onPageChange={goToReferralsPage}
            error={referralsError}
            onRetry={() => {
              setReferralsError(null);
              fetchReferrals();
            }}
            isLoading={isLoading}
          />
        )}
        {activeTab === 'kyc' && (
          <KycTab
            kycData={kycData}
            userKycStatus={user.kycStatus}
            userKycVerifiedAt={user.kycVerifiedAt}
            userKycExpiresAt={user.kycExpiresAt}
            error={kycError}
            onRetry={() => {
              setKycError(null);
              fetchKyc();
            }}
            onOverride={handleKycOverride}
          />
        )}
        {activeTab === 'accreditation' && (
          <AccreditationTab
            accreditationData={accreditationData}
            userAccreditationStatus={user.accreditationStatus}
            userAccreditationVerifiedAt={user.accreditationVerifiedAt}
            userAccreditationExpiresAt={user.accreditationExpiresAt}
            error={accreditationError}
            onRetry={() => {
              setAccreditationError(null);
              fetchAccreditation();
            }}
            onOverride={handleAccreditationOverride}
            onReview={handleAccreditationReview}
          />
        )}
      </div>
    </div>
  );
}

